function checkSecret(btn)
{
   if(btn == "star")
   {
      if(!star_checked)
      {
         star_checked = true;
      }
      else
      {
         star_checked = false;
      }
      star.active._visible = star_checked;
   }
   if(btn == "shell")
   {
      if(!shell_checked)
      {
         shell_checked = true;
      }
      else
      {
         shell_checked = false;
      }
      shell.active._visible = shell_checked;
   }
   if(star_checked && shell_checked)
   {
      penguin.silver._visible = true;
      penguin.pink._visible = false;
      penguin.fire._visible = false;
      silver_mc._visible = true;
      penguin.happy_face._visible = true;
      penguin.norm_face._visible = false;
   }
}
stop();
star.btn._alpha = 0;
star.btn._visible = false;
star.active._visible = false;
shell.btn._alpha = 0;
shell.btn._visible = false;
shell.active._visible = false;
penguin.pink._visible = false;
penguin.silver._visible = false;
penguin.happy_face._visible = false;
silver_mc._visible = false;
var star_checked = false;
var shell_checked = false;
penguin.onRelease = function()
{
   if(this.fire._visible)
   {
      this.fire._visible = false;
      this.pink._visible = true;
      star.btn._visible = true;
      shell.btn._visible = true;
   }
   else
   {
      this.fire._visible = true;
      this.pink._visible = false;
      star.btn._visible = false;
      shell.btn._visible = false;
      star.active._visible = false;
      shell.active._visible = false;
      star_checked = false;
      shell_checked = false;
      penguin.happy_face._visible = false;
      penguin.norm_face._visible = true;
   }
   penguin.silver._visible = false;
   silver_mc._visible = false;
};
star.btn.onRollOver = function()
{
   this._alpha = 50;
};
star.btn.onRollOut = function()
{
   this._alpha = 0;
};
star.btn.onRelease = function()
{
   checkSecret("star");
};
shell.btn.onRollOver = function()
{
   this._alpha = 50;
};
shell.btn.onRollOut = function()
{
   this._alpha = 0;
};
shell.btn.onRelease = function()
{
   checkSecret("shell");
};
